<!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Report Card - {{ $exam }}</title><style>*{box-sizing:border-box}body{font-family:Arial,sans-serif;background:#eef2f7;margin:0;color:#172033}.sheet{width:210mm;min-height:297mm;margin:12px auto;background:#fff;padding:13mm;border:2px solid #173f7a}.header{text-align:center;border-bottom:3px double #173f7a;padding-bottom:12px}.logo{width:72px;height:72px;object-fit:contain;float:left}.school{font-size:28px;font-weight:800;color:#173f7a}.subtitle{font-size:13px;margin-top:4px}.title{display:inline-block;margin-top:10px;padding:7px 24px;background:#173f7a;color:#fff;font-size:18px;font-weight:bold;border-radius:20px}.info{display:grid;grid-template-columns:1fr 1fr;gap:7px 30px;margin:20px 0;padding:12px;background:#f5f8fc;border:1px solid #ccd7e5}.info b{display:inline-block;min-width:110px}.exam{text-align:center;font-size:20px;font-weight:bold;margin:12px 0}table{width:100%;border-collapse:collapse}th,td{border:1px solid #8292a8;padding:9px;text-align:center}th{background:#173f7a;color:white}td:first-child{text-align:left}.summary{margin-top:18px;display:grid;grid-template-columns:repeat(4,1fr);gap:8px}.box{text-align:center;border:1px solid #9cabc0;padding:10px;background:#f7f9fc}.box strong{display:block;font-size:20px;color:#173f7a;margin-top:3px}.pass{color:#16803b!important}.fail{color:#b42318!important}.signatures{display:flex;justify-content:space-between;margin-top:70px;text-align:center}.sign{width:180px;border-top:1px solid #333;padding-top:6px;font-weight:bold}.actions{text-align:center;margin:16px}.actions button{background:#173f7a;color:#fff;border:0;padding:10px 24px;border-radius:6px;font-size:15px;cursor:pointer}@media print{@page{size:A4 portrait;margin:0}body{background:#fff}.sheet{margin:0;width:210mm;min-height:297mm;border:0}.actions{display:none}}</style></head><body><div class="actions"><button onclick="window.print()">Print Report Card</button></div><div class="sheet"><div class="header">@if($school?->logo)<img class="logo" src="{{ asset('storage/'.$school->logo) }}" alt="Logo">@endif<div class="school">{{ $school?->school_name ?: 'C-Net Pathshala' }}</div>@if($school?->address)<div class="subtitle">{{ $school->address }}</div>@endif<div class="title">STUDENT REPORT CARD</div><div style="clear:both"></div></div><div class="info"><div><b>Student Name:</b> {{ $student->user->name }}</div><div><b>Admission No.:</b> {{ $student->admission_no }}</div><div><b>Class:</b> {{ $student->class_name ?: '—' }}</div><div><b>Section:</b> {{ $student->section ?: '—' }}</div><div><b>Roll No.:</b> {{ $student->roll_no ?: '—' }}</div><div><b>Exam:</b> {{ $exam }}</div></div><div class="exam">Academic Performance</div><table><thead><tr><th>S.No.</th><th>Subject</th><th>Maximum Marks</th><th>Marks Obtained</th><th>Percentage</th><th>Remark</th></tr></thead><tbody>@foreach($results as $row)@php($sp=(float)$row->max_marks>0?round(((float)$row->marks_obtained/(float)$row->max_marks)*100,1):0)<tr><td style="text-align:center">{{ $loop->iteration }}</td><td>{{ $row->subject }}</td><td>{{ number_format((float)$row->max_marks,2) }}</td><td>{{ number_format((float)$row->marks_obtained,2) }}</td><td>{{ $sp }}%</td><td>{{ $row->remark ?: '—' }}</td></tr>@endforeach<tr style="font-weight:bold;background:#eef3f9"><td colspan="2">TOTAL</td><td>{{ number_format($total,2) }}</td><td>{{ number_format($obtained,2) }}</td><td>{{ $percentage }}%</td><td></td></tr></tbody></table><div class="summary"><div class="box">Percentage<strong>{{ $percentage }}%</strong></div><div class="box">Grade<strong>{{ $grade }}</strong></div><div class="box">Result<strong class="{{ $result==='PASS'?'pass':'fail' }}">{{ $result }}</strong></div><div class="box">Subjects<strong>{{ $results->count() }}</strong></div></div><div class="signatures"><div class="sign">Class Teacher</div><div class="sign">Parent / Guardian</div><div class="sign">Authorized Signature</div></div></div></body></html>